--
-- Table structure for table `analytics_snapshots`
--

DROP TABLE IF EXISTS `analytics_snapshots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `analytics_snapshots` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `social_account_id` int unsigned DEFAULT NULL COMMENT 'NULL = aggregate across all platforms',
  `platform` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = aggregate row',
  `snapshot_date` date NOT NULL,
  `period` enum('daily','weekly','monthly') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily',
  `followers` bigint unsigned NOT NULL DEFAULT '0',
  `impressions` bigint unsigned NOT NULL DEFAULT '0',
  `reach` bigint unsigned NOT NULL DEFAULT '0',
  `likes` int unsigned NOT NULL DEFAULT '0',
  `comments` int unsigned NOT NULL DEFAULT '0',
  `shares` int unsigned NOT NULL DEFAULT '0',
  `saves` int unsigned NOT NULL DEFAULT '0',
  `link_clicks` int unsigned NOT NULL DEFAULT '0',
  `profile_visits` int unsigned NOT NULL DEFAULT '0',
  `engagement_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_snapshot` (`user_id`,`snapshot_date`,`period`,`platform`),
  KEY `social_account_id` (`social_account_id`),
  KEY `idx_snap_user` (`user_id`),
  KEY `idx_snap_date` (`snapshot_date`),
  KEY `idx_snap_platform` (`platform`),
  CONSTRAINT `analytics_snapshots_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `analytics_snapshots_ibfk_2` FOREIGN KEY (`social_account_id`) REFERENCES `social_accounts` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1081 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

